-- kolletjies-kafee-sinoville (owner)
UPDATE businesses SET description = 'Kolletjies Kafee is a neighbourhood café, convenience shop and takeaway outlet at Sinoville Corner Shopping Mall on Braam Pretorius Street, serving the surrounding Sinoville, Magalieskruin, Montana and Wonderboom communities. It offers takeaway meals and everyday convenience items, and customer reviews frequently single out its slap chips as among the best in the area, alongside dishes such as hake and chips, prego rolls and sphatlho. The café has a long-standing local character: reviews describe it as having served the community for many years, with ownership changing hands over time while it has continued operating as an independent neighbourhood business rather than a franchise. It trades from early morning into the evening on most days, making it a practical stop for breakfast, lunch, a quick takeaway or everyday essentials. Kolletjies Kafee suits locals after an affordable meal on the go as well as residents picking up convenience items close to home.', description_enriched_at = datetime('now') WHERE slug = 'kolletjies-kafee-sinoville' AND description = 'A cafe and takeaway at Sinoville Corner shopping centre.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
